sect1.para:
  यो वैकल्पिक syntax else र elseif मा पनि लागू हुन्छ। तल वैकल्पिक ढाँचामा elseif र else सहितको if संरचना देखाइएको छ:



<?php
$a = 5;
if ($a == 5):
    echo "a equals 5";
    echo "...";
elseif ($a == 6):
    echo "a equals 6";
    echo "!!!";
else:
    echo "a is neither 5 nor 6";
endif;
?>


   &example.outputs;


a equals 5...
